@kt.kernel
def k(x=kt.In(8, 32), y=kt.Out(8, 32), z=kt.Out(8, 32)):
    for u in kt.par(1, on=kt.mg):
        for j in kt.range(2):
            kt.zero(4, 32)
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(1):
            r = c * 4 + t * 4
            for out in (y, z):
                kt.store(out[r : r + 4, :], kt.load(x[r : r + 4, :]))
